#!/usr/bin/env bash
# Question 3: Service ${Q3_APP} unreachable. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

kubectl create namespace "${Q3_NS}" --dry-run=client -o yaml | kubectl apply -f - >/dev/null
timeout 60 bash -c "until kubectl -n '${Q3_NS}' get serviceaccount default >/dev/null 2>&1; do sleep 1; done"
kubectl apply -f - <<EOF
apiVersion: apps/v1
kind: Deployment
metadata:
  name: ${Q3_APP}
  namespace: ${Q3_NS}
spec:
  replicas: 0
  selector:
    matchLabels: { app: ${Q3_APP} }
  template:
    metadata:
      labels: { app: ${Q3_APP} }
    spec:
      containers:
        - name: web
          image: nginx:1.27-alpine
          ports: [{ name: http, containerPort: 80 }]
          readinessProbe:
            httpGet: { path: /, port: http }
            periodSeconds: 5
---
apiVersion: v1
kind: Service
metadata:
  name: ${Q3_APP}
  namespace: ${Q3_NS}
spec:
  selector: { app: ${Q3_APP} }
  ports: [{ port: 80, targetPort: http }]
---
apiVersion: v1
kind: Pod
metadata:
  name: client
  namespace: ${Q3_NS}
spec:
  containers:
    - name: shell
      image: busybox:1.36
      command: ["sleep", "infinity"]
EOF
if ! kubectl -n "${Q3_NS}" wait --for=condition=Ready pod/client --timeout=180s; then
  kubectl -n "${Q3_NS}" describe pod/client >&2 || true
  exit 1
fi

case "${Q3_FAULT}" in
  selector-mismatch)
    kubectl -n "${Q3_NS}" patch service "${Q3_APP}" -p '{"spec":{"selector":{"app":"'"${Q3_APP}"'-v2"}}}'
    ;;
  target-port)
    kubectl -n "${Q3_NS}" patch service "${Q3_APP}" --type=json -p '[{"op":"replace","path":"/spec/ports/0/targetPort","value":8080}]'
    ;;
  named-port)
    kubectl -n "${Q3_NS}" patch deployment "${Q3_APP}" --type=json -p '[{"op":"replace","path":"/spec/template/spec/containers/0/ports/0/name","value":"web"},{"op":"replace","path":"/spec/template/spec/containers/0/readinessProbe/httpGet/port","value":"web"}]'
    ;;
  network-policy)
    kubectl -n "${Q3_NS}" apply -f - <<< '{"apiVersion":"networking.k8s.io/v1","kind":"NetworkPolicy","metadata":{"name":"'"${Q3_APP}"'-ingress"},"spec":{"podSelector":{"matchLabels":{"app":"'"${Q3_APP}"'"}},"policyTypes":["Ingress"],"ingress":[{"from":[{"podSelector":{"matchLabels":{"role":"monitoring"}}}]}]}}'
    ;;
  not-ready)
    kubectl -n "${Q3_NS}" patch deployment "${Q3_APP}" --type=json -p '[{"op":"replace","path":"/spec/template/spec/containers/0/readinessProbe/httpGet/path","value":"/ready"}]'
    ;;
  *)
    echo "unknown fault" >&2
    exit 1
    ;;
esac

kubectl -n "${Q3_NS}" scale "deployment/${Q3_APP}" --replicas=2
# The question only makes sense if the client really is cut off.
for _ in $(seq 1 30); do
  kubectl -n "${Q3_NS}" exec client -- wget -qO- -T 3 "http://${Q3_APP}" 2>/dev/null | grep -q nginx || exit 0
  sleep 2
done
echo "the client can still reach the service" >&2
exit 1
